fn parse<T: serde::de::DeserializeOwned>(s: &str) -> Result<T, ErrorCode> {
    serde_json::from_str(s).map_err(|_| ErrorCode::InvalidMessage)
}

/// Serialises any frame of this module.
pub fn to_json<T: Serialize>(frame: &T) -> String {
    serde_json::to_string(frame).unwrap_or_default()
}
